import{_ as o,o as i,c as t,a2 as l}from"./chunks/framework.BKjcr3i4.js";const p=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{"title":"Keyboard Shortcuts","audience":"public","status":"draft","owner":"core-team"},"headers":[],"relativePath":"guide/keyboard-shortcuts.md","filePath":"guide/keyboard-shortcuts.md"}'),a={name:"guide/keyboard-shortcuts.md"};function c(d,e,r,n,s,u){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>This page centralizes the editor keyboard interactions by component/workflow.</p><h2 id="scope-rules" tabindex="-1">Scope Rules <a class="header-anchor" href="#scope-rules" aria-label="Permalink to &quot;Scope Rules&quot;">​</a></h2><ul><li>Most shortcuts apply only when focus is in the code editor or preview.</li><li>Shortcuts are ignored while typing in native form controls outside OmniUI Editor (<code>input</code>, <code>textarea</code>, <code>select</code>).</li><li>Arrow-based shortcuts use this direction rule by default: <ul><li>previous: <code>Left</code> or <code>Up</code></li><li>next: <code>Right</code> or <code>Down</code></li></ul></li></ul><h2 id="tabs-and-navigation-groups-tab-navitem-tabs" tabindex="-1">Tabs and Navigation Groups (<code>Tab</code>, <code>NavItem</code>, <code>Tabs</code>) <a class="header-anchor" href="#tabs-and-navigation-groups-tab-navitem-tabs" aria-label="Permalink to &quot;Tabs and Navigation Groups (`Tab`, `NavItem`, `Tabs`)&quot;">​</a></h2><p>Use these while your cursor/selection is inside a tabs or navigation group.</p><ul><li>Cycle active item: <ul><li>macOS: <code>Option + Left/Right</code> or <code>Cmd + Left/Right</code></li><li>Windows/Linux: <code>Alt + Left/Right</code></li></ul></li><li>Reorder selected item: <ul><li>macOS: <code>Option + Shift + Up/Down</code> or <code>Cmd + Shift + Up/Down</code></li><li>Windows/Linux: <code>Alt + Shift + Up/Down</code></li></ul></li><li>Show shortcut hint toast: <ul><li><code>F1</code></li><li><code>Alt + /</code></li></ul></li></ul><h2 id="datagrid" tabindex="-1">DataGrid <a class="header-anchor" href="#datagrid" aria-label="Permalink to &quot;DataGrid&quot;">​</a></h2><p>Use these while selection/caret is inside a DataGrid table row.</p><ul><li>Cycle active column focus: <ul><li>macOS: <code>Option + Left/Right</code> or <code>Cmd + Left/Right</code></li><li>Windows/Linux: <code>Alt + Left/Right</code></li></ul></li><li>Reorder current column: <ul><li>macOS: <code>Option + Shift + Left/Right</code> or <code>Cmd + Shift + Left/Right</code></li><li>Windows/Linux: <code>Alt + Shift + Left/Right</code></li></ul></li></ul><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><p>Use while selection is on or near an <code>Input</code> component.</p><ul><li>Cycle Input presets: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><h2 id="button" tabindex="-1">Button <a class="header-anchor" href="#button" aria-label="Permalink to &quot;Button&quot;">​</a></h2><p>Use while selection is on or near a <code>Button</code> component.</p><ul><li>Cycle Button presets: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><p>Behavior:</p><ul><li>Vertical arrows switch variant families.</li><li>Horizontal arrows switch interaction state presets.</li></ul><h2 id="select" tabindex="-1">Select <a class="header-anchor" href="#select" aria-label="Permalink to &quot;Select&quot;">​</a></h2><p>Use while selection is on or near a <code>Select</code> component.</p><ul><li>Cycle Select presets: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><h2 id="spinbutton" tabindex="-1">SpinButton <a class="header-anchor" href="#spinbutton" aria-label="Permalink to &quot;SpinButton&quot;">​</a></h2><p>Use while selection is on or near a <code>SpinButton</code> component.</p><ul><li>Cycle SpinButton presets: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><h2 id="overlays-drawer-bottom-sheet-dialog-modal-popover-tooltip" tabindex="-1">Overlays (<code>Drawer</code>, <code>Bottom Sheet</code>, <code>Dialog</code>, <code>Modal</code>, <code>Popover</code>, <code>Tooltip</code>) <a class="header-anchor" href="#overlays-drawer-bottom-sheet-dialog-modal-popover-tooltip" aria-label="Permalink to &quot;Overlays (`Drawer`, `Bottom Sheet`, `Dialog`, `Modal`, `Popover`, `Tooltip`)&quot;">​</a></h2><p>Use while selection is on or near an overlay directive of the same type.</p><ul><li>Cycle overlay presets: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><p>Behavior:</p><ul><li>Horizontal arrows rotate placement options.</li><li>Vertical arrows rotate variant options.</li></ul><p>Tooltip variant behavior:</p><ul><li><code>Up/Down</code> toggles tooltip style variants (<code>default</code> / <code>inverted</code>) while preserving <code>placement</code>.</li><li><code>Left/Right</code> rotates the full placement ring (<code>top-left</code> → ... → <code>left-top</code> → <code>none</code> → <code>center</code>) while preserving variant attrs.</li></ul><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><p>Use while selection is on a <code>~ Stack</code> directive line (not inside a component line).</p><ul><li>Set stack direction: <ul><li>macOS: <code>Option + Arrow</code></li><li>Windows/Linux: <code>Alt + Arrow</code></li></ul></li></ul><p>Behavior:</p><ul><li><code>Left/Right</code> sets <code>horizontal</code>.</li><li><code>Up/Down</code> sets <code>vertical</code>.</li></ul><h2 id="virtual-template-editor" tabindex="-1">Virtual Template Editor <a class="header-anchor" href="#virtual-template-editor" aria-label="Permalink to &quot;Virtual Template Editor&quot;">​</a></h2><p>When virtual template mode is active and focus is on a virtual-template field:</p><ul><li>Cycle field values: <ul><li>macOS: <code>Cmd + Arrow</code></li></ul></li></ul><h2 id="general-editor-and-preview" tabindex="-1">General Editor and Preview <a class="header-anchor" href="#general-editor-and-preview" aria-label="Permalink to &quot;General Editor and Preview&quot;">​</a></h2><ul><li>Toggle Design Mode: <ul><li>macOS: <code>Cmd + Shift + D</code></li><li>Windows/Linux: <code>Ctrl + Shift + D</code></li></ul></li><li>Copy selected preview node SVG (when preview is active/hovered/selected): <ul><li>macOS: <code>Cmd + Shift + C</code></li><li>Windows/Linux: <code>Ctrl + Shift + C</code></li></ul></li><li>Open Find &amp; Replace: <ul><li>macOS: <code>Cmd + F</code></li><li>Windows/Linux: <code>Ctrl + F</code></li></ul></li></ul><h2 id="escape-behavior" tabindex="-1">Escape Behavior <a class="header-anchor" href="#escape-behavior" aria-label="Permalink to &quot;Escape Behavior&quot;">​</a></h2><ul><li><code>Esc</code> closes About dialog if open.</li><li><code>Esc</code> exits DataGrid editor affordances if open.</li><li><code>Esc</code> exits Design Mode if active.</li><li><code>Esc</code> closes Virtual Template Editor if active.</li><li><code>Esc</code> clears locked preview inspect target.</li></ul>',43)])])}const m=o(a,[["render",c]]);export{p as __pageData,m as default};
